R=Path(__file__).resolve().parents[1];A=R/'assets/samples';A.mkdir(exist_ok=True)
brief={'Business':'Luna Braids (fictional practice business)','Location':'Abuja, Nigeria','Services':'Braiding consultation, protective-style appointment, braid-care advice','Hours':'Tuesday–Saturday, 10:00–18:00 (practice input)','Price rule':'Quote after consultation; no invented fixed prices or discounts','Booking':'[replace with owner-approved booking link]','Audience':'People comparing protective-style options and maintenance needs','Voice':'Clear, warm, practical; no miracle growth or health claims','Photos':'Owner-approved service photos; identifiable clients require permission','Scope':'Seven captions, three reusable designs, one revision, editable files and handoff','Exclusions':'Posting, account access, paid ads, sales/booking guarantees','Approval':'Owner checks facts, photos, booking link, and captions before use'}
rows=[
 ('Tuesday','Choose the right consultation','Service card','Not sure which braid style to ask for?','Bring a reference photo and tell us about your usual routine. A consultation helps us discuss the style, appointment requirements, and maintenance questions before you book.','Ask about a consultation through [booking link].'),
 ('Wednesday','Preparation FAQ','FAQ layout','What should I confirm before my appointment?','Ask the salon about hair preparation, expected appointment length, and anything you need to bring. Confirm the instructions for your chosen service rather than guessing from a general video.','Send your preparation question to [booking link].'),
 ('Thursday','Care education','Care checklist','Your braid-care questions deserve specific answers.','Tell us about the style you are considering and how you usually maintain it. We can explain the care guidance for that service and the questions to ask at your consultation.','Save your questions and ask us at [booking link].'),
 ('Friday','Process overview','Process layout','A clear appointment starts with a clear brief.','Share your reference, preferred appointment date, and the questions you want answered. We will confirm the service details and next step before the appointment is agreed.','Start your inquiry at [booking link].'),
 ('Saturday','Opening hours','Service card','Planning a salon visit this week?','Our practice opening hours are Tuesday–Saturday, 10:00–18:00. Ask about available appointment times before traveling; opening hours do not mean every slot is available.','Check availability through [booking link].'),
 ('Sunday','Consultation questions','FAQ layout','Three questions to bring to a braid consultation.','What preparation does this style need? How long should I allow for the appointment? What care routine should I follow afterward? Bring a reference and ask the salon to explain what applies to your chosen service.','Keep this list for your next consultation.'),
 ('Monday','Next-week planning','Process layout','A reference photo is a useful starting point.','Pair it with your routine, preferred appointment day, and any maintenance questions. That gives the salon useful information for discussing your options.','Send your reference and questions via [booking link].')]
colors=[('#6428ce','#f6f3eb'),('#213d31','#eff1d8'),('#201b29','#e9ddfa')]
for i,(title,sub) in enumerate([('START WITH A CONSULTATION','Reference • Routine • Questions'),('BEFORE YOUR APPOINTMENT','Preparation • Time • What to bring'),('MAKE THE NEXT STEP CLEAR','Reference → Details → Confirm')]):
 bg,fg=colors[i]
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1080 1350"><rect width="1080" height="1350" fill="{bg}"/><text x="88" y="120" fill="{fg}" font-family="sans-serif" font-size="26" letter-spacing="4">LUNA BRAIDS / PRACTICE DESIGN</text><path d="M88 230h904" stroke="{fg}"/><text x="88" y="400" fill="{fg}" font-family="sans-serif" font-size="65" font-weight="bold">{E(title.split(' ',2)[0])}</text><foreignObject x="88" y="465" width="880" height="440"><div xmlns="http://www.w3.org/1999/xhtml" style="font:700 82px/1.1 sans-serif;color:{fg}">{E(' '.join(title.split(' ')[1:]))}</div></foreignObject><text x="88" y="1040" fill="{fg}" font-family="sans-serif" font-size="29">{E(sub)}</text><rect x="88" y="1120" width="904" height="108" fill="{fg}"/><text x="120" y="1188" fill="{bg}" font-family="sans-serif" font-size="29">Ask through your approved booking link</text></svg>'''
 (A/f'salon-layout-{i+1}.svg').write_text(svg)
base='''<style>body{margin:0;background:#f6f3eb;color:#201b29;font:17px/1.65 system-ui,sans-serif}main{max-width:1050px;margin:auto;padding:40px 24px}h1{font-size:54px;line-height:1.05;max-width:850px}h2{font-size:30px;margin-top:44px}h3{font-size:22px}table{border-collapse:collapse;width:100%;font-size:14px}th,td{border:1px solid #d7cadd;padding:12px;text-align:left;vertical-align:top}th{background:#e9ddfa}.scroll{overflow:auto}.note{padding:20px;background:#e9ddfa;border-left:4px solid #6428ce}.card{background:white;border:1px solid #ded8e7;padding:22px;margin:18px 0}.designs{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.designs img{width:100%}a{color:#6428ce}button{padding:12px;background:#6428ce;color:white;border:0;cursor:pointer}textarea{width:95%;min-height:80px;padding:12px;font:inherit}input{padding:8px;max-width:95%}@media(max-width:600px){h1{font-size:38px}.designs{grid-template-columns:1fr}main{padding:24px 16px}}@media print{button,.no-print{display:none}body{background:white}main{padding:0}h2{break-after:avoid}.card{break-inside:avoid}textarea{border:1px solid #999}a{color:inherit}}</style>'''
def page(name,title,body):
 (A/name).write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)}</title>{base}</head><body><main><p class="no-print"><a href="/index.html#results">← Blueprint examples</a></p><p>AI INCOME BLUEPRINT / FICTIONAL WORKED EXAMPLE</p><h1>{E(title)}</h1>{body}<p class="no-print"><button onclick="window.print()">Print or save as PDF</button></p></main></body></html>')
briefrows=''.join(f'<tr><th>{E(k)}</th><td>{E(v)}</td></tr>' for k,v in brief.items())
calendar='<div class="scroll"><table><thead><tr><th>Day</th><th>Job</th><th>Visual</th><th>Approval</th></tr></thead><tbody>'+''.join(f'<tr><td>{E(d)}</td><td>{E(topic)}</td><td>{E(visual)}</td><td>Pending owner review</td></tr>' for d,topic,visual,*_ in rows)+'</tbody></table></div>'
captions=''.join(f'<article class="card"><h3>{E(d)} · {E(topic)}</h3><p><strong>{E(hook)}</strong></p><p>{E(body)}</p><p>{E(cta)}</p><p><small>Filename: {i+1:02}-{d.lower()}.txt · Replace bracketed link. Owner review required.</small></p></article>' for i,(d,topic,visual,hook,body,cta) in enumerate(rows))
designs='<div class="designs">'+''.join(f'<article><img src="salon-layout-{i}.svg" alt="Fictional salon layout {i}"><p><a href="salon-layout-{i}.svg" download>Download editable SVG {i}</a></p></article>' for i in [1,2,3])+'</div>'
qa='''<ul><li>Services and hours match the approved brief.</li><li>No invented prices, booking availability, promotions, or hair-growth claims.</li><li>Replace every [booking link] and open the actual destination.</li><li>Obtain permission for client photos and identifiable people.</li><li>Read every design on a phone. Verify text and export dimensions.</li><li>Confirm the calendar, filenames, posting owner, and revision limit.</li><li>Record reach and inquiries only if actual measurements are available.</li></ul>'''
page('salon-content-pack.html','Luna Braids: a complete content-service handoff',f'''<div class="note">This is a fictional delivery reference, not a commissioned client result. The captions and three SVG layouts are filled. The booking link remains a placeholder deliberately: replace it with the owner-approved link before using the pack.</div><h2>1. Approved brief</h2><table>{briefrows}</table><h2>2. Seven-post calendar</h2>{calendar}<h2>3. Raw draft → edited caption</h2><div class="card"><p><b>Raw:</b> Get gorgeous, world-class braids with the best salon in Abuja. Book now before slots disappear!</p><p><b>Edited:</b> Not sure which braid style to ask for? Bring a reference photo and tell us about your usual routine. A consultation helps us discuss the style and maintenance questions before you book. Ask about a consultation through [booking link].</p><p><b>Why:</b> Removes unsupported ranking and scarcity. Gives the reader a useful next step supported by the brief.</p></div><h2>4. Seven finished captions</h2>{captions}<h2>5. Three reusable designs</h2><p>1080 × 1350 SVGs. Open in a compatible design editor, replace practice business details, and export PNG. Add approved photography only after permission. Recreate the hierarchy in Canva if SVG import is unavailable.</p>{designs}<h2>6. Delivery QA</h2>{qa}<h2>7. Folder structure and handoff</h2><div class="card"><p>01-brief / 02-calendar / 03-captions / 04-designs / 05-instructions</p><p>Hi Luna team, your seven-post pack is ready: [folder link]. Start with the calendar, then match each day to its numbered caption and design. Please confirm the services, hours, booking link, and image permissions before posting. You are responsible for publishing and responding to inquiries. The agreed scope includes one revision round; send all requested changes in one list by [agreed date]. I have included editable layouts and a short walkthrough showing the file order. Please reply “approved” or return the revision list.</p></div><h2>8. Revision request</h2><table><tr><th>File</th><th>Current text</th><th>Requested change</th><th>Reason / confirmed fact</th></tr><tr><td>05-saturday.txt</td><td>Tuesday–Saturday 10:00–18:00</td><td>[owner correction]</td><td>[approved new hours]</td></tr></table><h2>9. Reporting without invented results</h2><p>Delivered: seven captions and three designs. Approval: pending. Posts published: not yet measured. Reach, inquiries, bookings: unavailable. Next action: obtain approval, publish the agreed posts, then record the actual metrics. Ask which parts the owner could use without help.</p><p><a href="/playbooks/playbook-f-content-service.html">Follow the prompts and delivery steps in F</a></p>''')
page('salon-week-starter.html','Salon Week Starter: a complete reusable product',f'''<div class="note">A fictional product prototype to inspect and adapt. It helps plan a week of salon content. It does not promise bookings. Suggested $19 price in the playbook is a practice assumption, not proven demand. The complete instructions, filled example, worksheet, and replies are below.</div><h2>Start here: how to use this product</h2><ol><li>Gather your services, opening hours, booking URL, approved photos, and claim restrictions.</li><li>Fill the brief worksheet below. Do not publish until essential facts are confirmed.</li><li>Read the filled calendar and captions. Choose the post purpose, then substitute your facts.</li><li>Complete your blank calendar. Make the three layouts in your editor using the design references.</li><li>Check the QA list, preview on mobile, and confirm the booking link.</li><li>Save or print your completed work before closing this page. The editable fields do not auto-save.</li></ol><h2>Your reusable brief</h2>{''.join(f'<label><p>{E(k)}<br><textarea placeholder="Your confirmed {E(k.lower())}"></textarea></p></label>' for k in ['Business and audience','Services and price rules','Opening hours and booking link','Brand voice and photo permissions'])}<h2>Filled practice calendar</h2>{calendar}<h2>Your seven-day planning worksheet</h2><div class="scroll"><table><tr><th>Day</th><th>Reader question / purpose</th><th>Visual</th><th>CTA and approval</th></tr>{''.join(f'<tr><td>Day {i}</td><td><textarea aria-label="Day {i} purpose"></textarea></td><td><textarea aria-label="Day {i} visual"></textarea></td><td><textarea aria-label="Day {i} CTA"></textarea></td></tr>' for i in range(1,8))}</table></div><h2>Seven adaptable caption examples</h2>{captions}<h2>Three layout references</h2>{designs}<h2>Booking inquiry replies</h2><article class="card"><p><b>New inquiry:</b> Thanks for reaching out. Which service are you considering, and what day would suit you? Please send a reference if useful. We will confirm details and availability before agreeing the appointment.</p><p><b>Preparation question:</b> Thanks. Please tell us your chosen service so the owner can confirm the right preparation instructions. We do not want to give you generic instructions that may not apply.</p><p><b>Price question:</b> We quote after confirming the service details. Send [required details] through [approved booking channel], and the owner will explain the price and next step.</p></article><h2>Quality checklist</h2>{qa}<h2>What to measure</h2><p>Record published posts, actual link clicks, qualified inquiries, and confirmed appointments separately. Note where an inquiry came from if the person tells you. Do not attribute every booking to the calendar.</p><h2>Seller packaging reference</h2><p>Include this complete file, editable layout references, a preview, and a plain instructions sheet. State compatibility, what is editable, delivery method, support, and your actual refund policy on the product page. Test download access in test mode and open every file on mobile before launch.</p><p><a href="/playbooks/playbook-b-launch-product.html">Build and validate your own product in B</a></p>''')
